    private static int[] ints(String value){String[] words=value.split(",");int[] out=new int[words.length];for(int n=0;n<words.length;n++)out[n]=Integer.parseInt(words[n]);return out;}
    private static byte[] bytes(Dc3PpParticles p)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();p.save(new DataOutputStream(b));return b.toByteArray();}
    private static byte[] bytes(Dc3Petals p)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();p.save(new DataOutputStream(b));return b.toByteArray();}
    private static Dc3PpParticles fromSeed(int[] seed)throws IOException{
        ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.writeInt(0x50503431);out.writeInt(0);out.writeBoolean(false);out.writeBoolean(true);for(int value:seed)out.writeInt(value);out.writeLong(0);out.writeLong(0);out.writeInt(0);out.writeInt(0);out.writeInt(0);for(int n=0;n<1300;n++)out.writeInt(0);return Dc3PpParticles.load(new DataInputStream(new ByteArrayInputStream(b.toByteArray())));
    }
    private static void word(ByteArrayOutputStream out,int value){for(int n=0;n<4;n++)out.write(value>>>(n*8)&255);}
    private static String sha(byte[] input)throws Exception{byte[] hash=MessageDigest.getInstance("SHA-256").digest(input);StringBuilder out=new StringBuilder();for(byte value:hash)out.append(String.format("%02x",value&255));return out.toString();}
    private static String stateHash(Dc3PpParticles p)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();for(int n=0;n<50;n++)for(int value:p.slot(n))word(out,value);return sha(out.toByteArray());}
    private static String drawHash(Dc3PpParticles p)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();for(Dc3PpParticles.Sprite a:p.sprites())for(int value:new int[]{a.object,a.x,a.y,a.x+a.width,a.y+a.height,a.sx,a.sy,a.surface,a.mode})word(out,value);return sha(out.toByteArray());}
    public static int run()throws Exception{
        checks=0;
        for(String vector:VECTORS){String[] v=vector.split("\\|");Dc3PpParticles p=fromSeed(ints(v[0]));p.command(Integer.parseInt(v[1]),Boolean.parseBoolean(v[2]));for(int n=0;n<Integer.parseInt(v[3]);n++)p.tick();String id=v[1]+"/"+v[3];check(stateHash(p).equals(v[4]),"PP4 native record hash "+id);check(Arrays.equals(p.randomWords(),ints(v[5])),"PP4 native RNG "+id);check(p.toggle()==Integer.parseInt(v[6]),"PP4 native toggle "+id);check(Arrays.equals(new int[]{p.windKind(),p.windX()},ints(v[7])),"PP4 native wind "+id);check(drawHash(p).equals(v[8]),"PP4 native draw journal "+id);Dc3PpParticles copy=Dc3PpParticles.load(new DataInputStream(new ByteArrayInputStream(bytes(p))));check(Arrays.equals(bytes(p),bytes(copy)),"PP4 oracle snapshot "+id);}
        Dc3Petals p=new Dc3Petals();p.startPp4(0x42,true);p.elapse(103);Dc3Petals copy=p.copy();check(Arrays.equals(bytes(p),bytes(copy)),"PP4 in-flight copy");p.elapse(897);for(int n=0;n<897;n++)copy.elapse(1);check(Arrays.equals(bytes(p),bytes(copy)),"PP4 clock partition and restored continuation");check(p.pp4().activeCount()==10&&p.particles.isEmpty()&&p.effect==4,"PP4 independent typed owner");
        byte[] before=bytes(p);byte[] bad=before.clone();bad[4]^=1;try{new Dc3Petals().load(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("PP4 bad magic accepted");}catch(IOException expected){checks++;}
        int[] rng=p.pp4().randomWords();int toggle=p.pp4().toggle();p.startPp4(0,true);check(p.pp4().activeCount()==0&&p.pp4().sprites().isEmpty()&&!p.pp4().running(),"PP4 zero strength release");check(Arrays.equals(rng,p.pp4().randomWords())&&toggle==p.pp4().toggle(),"PP4 release preserves RNG and toggle");check(Arrays.equals(bytes(p),bytes(p.copy())),"PP4 stopped snapshot");p.start(1,2);check(p.pp4()==null&&p.effect==1&&p.particles.size()==10,"DD switch drops PP owner");
        Dc3Petals dd=new Dc3Petals();byte[] empty=bytes(dd);check(empty.length==28&&empty[3]==1&&empty[7]==1,"DD existing empty codec unchanged");check(Arrays.equals(empty,bytes(dd.copy())),"DD codec remains readable");
        Dc3PpParticles capped=new Dc3PpParticles();capped.command(0x45,true);capped.elapse(Long.MAX_VALUE);check(capped.frames()==3600&&capped.remainder()>=0&&capped.remainder()<1000,"PP4 bounded catch-up without time overflow");
        return checks;
    }
    public static void main(String[] args)throws Exception{System.out.println("PP4 particle checks "+run());}
